        {
            var line = raw.TrimEnd('\r');
            if (line == "  model_group_alias:") { inBlock = true; continue; }
            if (!inBlock) continue;
            if (line.Length > 0 && !line.StartsWith("    ")) break;
            var t = line.TrimStart();
